// ─── CryptoPay SDK — API Client ─────────────────────────────
// Lightweight fetch-based API client (zero deps)

export interface CreatePaymentParams {
  apiKey: string
  orderId: string
  amount: string
  currency: string
  paymentMethod?: 'DIRECT' | 'CONTRACT'
}

export interface PaymentResponse {
  paymentId: string
  paymentAddress: string
  qrCodeUrl: string
  status: 'PENDING' | 'CONFIRMED' | 'FAILED'
  amount: string
  currency: string
}

export interface PaymentStatusResponse {
  paymentId: string
  status: 'PENDING' | 'CONFIRMED' | 'FAILED'
  txHash?: string
}

export class CryptoPayAPI {
  private baseUrl: string

  constructor(baseUrl: string = 'https://api.cryptopay.dev') {
    this.baseUrl = baseUrl.replace(/\/$/, '')
  }

  async createPayment(params: CreatePaymentParams): Promise<PaymentResponse> {
    const res = await fetch(`${this.baseUrl}/payments`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        apiKey: params.apiKey,
        orderId: params.orderId,
        amount: params.amount,
        currency: params.currency,
        paymentMethod: params.paymentMethod || 'DIRECT',
      }),
    })

    if (!res.ok) {
      const err = await res.json().catch(() => ({ error: 'Network error' }))
      throw new Error(err.error || `HTTP ${res.status}`)
    }

    return res.json()
  }

  async getPaymentStatus(paymentId: string): Promise<PaymentStatusResponse> {
    const res = await fetch(`${this.baseUrl}/payments/${paymentId}`)

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`)
    }

    return res.json()
  }
}
