// ─── CryptoPay SDK — Checkout Widget ────────────────────────
// Self-contained embeddable payment widget
// Renders inline (no iframe) with scoped CSS

import { CryptoPayAPI, PaymentResponse } from './api'
import { detectWallets, DetectedWallet, connectWallet, executeTransaction, isMobileDevice, getMobileDeepLinks } from './wallet'
import './styles/widget.css'

export interface CheckoutConfig {
  apiKey: string
  amount: string
  currency: string
  orderId?: string
  baseUrl?: string
  theme?: 'dark' | 'light'
  onSuccess?: (payment: PaymentResponse) => void
  onError?: (error: string) => void
  onStatusChange?: (status: string) => void
}

type WidgetState = 'idle' | 'loading' | 'method-select' | 'qr' | 'wallet-pending' | 'polling' | 'success' | 'error'

export class CryptoPayCheckout {
  private config: CheckoutConfig
  private api: CryptoPayAPI
  private container: HTMLElement | null = null
  private state: WidgetState = 'idle'
  private payment: PaymentResponse | null = null
  private wallets: DetectedWallet[] = []
  private pollInterval: ReturnType<typeof setInterval> | null = null
  private errorMessage: string = ''

  constructor(config: CheckoutConfig) {
    this.config = config
    this.api = new CryptoPayAPI(config.baseUrl)
    this.wallets = detectWallets()
  }

  mount(selector: string): void {
    const el = document.querySelector(selector)
    if (!el) {
      console.error(`[CryptoPay] Element not found: ${selector}`)
      return
    }
    this.container = el as HTMLElement
    this.container.classList.add('cpay-root')
    if (this.config.theme === 'light') {
      this.container.classList.add('cpay-light')
    }
    this.setState('method-select')
  }

  unmount(): void {
    this.stopPolling()
    if (this.container) {
      this.container.innerHTML = ''
      this.container.classList.remove('cpay-root', 'cpay-light')
    }
  }

  private setState(state: WidgetState): void {
    this.state = state
    this.config.onStatusChange?.(state)
    this.render()
  }

  private render(): void {
    if (!this.container) return
    this.container.innerHTML = ''

    const widget = this.el('div', 'cpay-widget')

    // Header
    const header = this.el('div', 'cpay-header')
    header.innerHTML = `
      <div class="cpay-logo">⟐ <span>CryptoPay</span></div>
      <div class="cpay-amount">${this.config.amount} <span class="cpay-currency">${this.config.currency}</span></div>
    `
    widget.appendChild(header)

    // Body
    const body = this.el('div', 'cpay-body')

    switch (this.state) {
      case 'loading':
        body.appendChild(this.renderLoading())
        break
      case 'method-select':
        body.appendChild(this.renderMethodSelect())
        break
      case 'qr':
        body.appendChild(this.renderQR())
        break
      case 'wallet-pending':
        body.appendChild(this.renderWalletPending())
        break
      case 'polling':
        body.appendChild(this.renderPolling())
        break
      case 'success':
        body.appendChild(this.renderSuccess())
        break
      case 'error':
        body.appendChild(this.renderError())
        break
    }

    widget.appendChild(body)

    // Footer
    const footer = this.el('div', 'cpay-footer')
    footer.innerHTML = `<span class="cpay-secure">🔒 Secured by CryptoPay</span>`
    widget.appendChild(footer)

    this.container.appendChild(widget)
  }

  // ─── Render States ─────────────────────────────────────

  private renderMethodSelect(): HTMLElement {
    const wrap = this.el('div', 'cpay-methods')

    // QR / Direct transfer option (always available)
    const qrBtn = this.el('button', 'cpay-method-btn')
    qrBtn.innerHTML = `
      <span class="cpay-method-icon">📱</span>
      <div class="cpay-method-info">
        <strong>QR Code / Direct Transfer</strong>
        <span>Scan or copy wallet address</span>
      </div>
      <span class="cpay-method-arrow">→</span>
    `
    qrBtn.addEventListener('click', () => this.startDirectPayment())
    wrap.appendChild(qrBtn)

    // Wallet options
    if (this.wallets.length > 0) {
      for (const wallet of this.wallets) {
        const btn = this.el('button', 'cpay-method-btn')
        btn.innerHTML = `
          <span class="cpay-method-icon">${wallet.icon}</span>
          <div class="cpay-method-info">
            <strong>${wallet.name}</strong>
            <span>Pay with browser wallet</span>
          </div>
          <span class="cpay-method-arrow">→</span>
        `
        btn.addEventListener('click', () => this.startWalletPayment(wallet))
        wrap.appendChild(btn)
      }
    } else if (isMobileDevice()) {
      // Mobile deep links
      const links = getMobileDeepLinks(window.location.href)
      for (const [name, url] of Object.entries(links)) {
        const btn = this.el('a', 'cpay-method-btn') as HTMLAnchorElement
        btn.href = url
        btn.target = '_blank'
        const displayName = name.charAt(0).toUpperCase() + name.slice(1)
        btn.innerHTML = `
          <span class="cpay-method-icon">📲</span>
          <div class="cpay-method-info">
            <strong>Open in ${displayName}</strong>
            <span>Pay via mobile wallet</span>
          </div>
          <span class="cpay-method-arrow">→</span>
        `
        wrap.appendChild(btn)
      }
    }

    return wrap
  }

  private renderQR(): HTMLElement {
    const wrap = this.el('div', 'cpay-qr-view')

    if (!this.payment) return wrap

    // QR Code
    const qrContainer = this.el('div', 'cpay-qr-container')
    const canvas = document.createElement('canvas')
    canvas.id = 'cpay-qr-canvas'
    qrContainer.appendChild(canvas)
    wrap.appendChild(qrContainer)

    // Render QR after DOM insert
    setTimeout(() => {
      try {
        // Use dynamic import since qrcode is bundled
        const qrValue = this.payment?.qrCodeUrl || `ethereum:${this.payment?.paymentAddress}`
        this.renderQRToCanvas(canvas, qrValue)
      } catch {}
    }, 50)

    // Address display
    const addr = this.el('div', 'cpay-address-box')
    const shortAddr = this.payment.paymentAddress
      ? `${this.payment.paymentAddress.slice(0, 8)}...${this.payment.paymentAddress.slice(-6)}`
      : ''
    addr.innerHTML = `
      <span class="cpay-address-label">Send ${this.config.amount} ${this.config.currency} to:</span>
      <div class="cpay-address-row">
        <code class="cpay-address">${this.payment.paymentAddress}</code>
        <button class="cpay-copy-btn" id="cpay-copy">📋</button>
      </div>
    `
    wrap.appendChild(addr)

    // Copy handler
    setTimeout(() => {
      const copyBtn = document.getElementById('cpay-copy')
      copyBtn?.addEventListener('click', () => {
        navigator.clipboard.writeText(this.payment?.paymentAddress || '')
        if (copyBtn) copyBtn.textContent = '✓'
        setTimeout(() => { if (copyBtn) copyBtn.textContent = '📋' }, 2000)
      })
    }, 50)

    // Status + Back
    const actions = this.el('div', 'cpay-actions')
    actions.innerHTML = `<span class="cpay-status-dot"></span> Waiting for payment...`

    const backBtn = this.el('button', 'cpay-back-btn')
    backBtn.textContent = '← Back'
    backBtn.addEventListener('click', () => {
      this.stopPolling()
      this.setState('method-select')
    })
    actions.appendChild(backBtn)
    wrap.appendChild(actions)

    return wrap
  }

  private renderWalletPending(): HTMLElement {
    const wrap = this.el('div', 'cpay-pending')
    wrap.innerHTML = `
      <div class="cpay-spinner"></div>
      <p class="cpay-pending-text">Confirm the transaction in your wallet...</p>
      <p class="cpay-pending-sub">Do not close this window</p>
    `
    return wrap
  }

  private renderPolling(): HTMLElement {
    const wrap = this.el('div', 'cpay-pending')
    wrap.innerHTML = `
      <div class="cpay-spinner"></div>
      <p class="cpay-pending-text">Transaction submitted!</p>
      <p class="cpay-pending-sub">Waiting for blockchain confirmation...</p>
    `
    return wrap
  }

  private renderSuccess(): HTMLElement {
    const wrap = this.el('div', 'cpay-success')
    wrap.innerHTML = `
      <div class="cpay-check">✓</div>
      <p class="cpay-success-text">Payment Confirmed!</p>
      <p class="cpay-success-sub">Transaction verified on-chain</p>
    `
    return wrap
  }

  private renderError(): HTMLElement {
    const wrap = this.el('div', 'cpay-error-view')
    const retryBtn = this.el('button', 'cpay-retry-btn')
    retryBtn.textContent = 'Try Again'
    retryBtn.addEventListener('click', () => this.setState('method-select'))

    wrap.innerHTML = `
      <div class="cpay-error-icon">✕</div>
      <p class="cpay-error-text">${this.errorMessage || 'Payment failed'}</p>
    `
    wrap.appendChild(retryBtn)
    return wrap
  }

  private renderLoading(): HTMLElement {
    const wrap = this.el('div', 'cpay-pending')
    wrap.innerHTML = `
      <div class="cpay-spinner"></div>
      <p class="cpay-pending-text">Creating payment...</p>
    `
    return wrap
  }

  // ─── Payment Flows ────────────────────────────────────

  private async startDirectPayment(): Promise<void> {
    this.setState('loading')
    try {
      this.payment = await this.api.createPayment({
        apiKey: this.config.apiKey,
        orderId: this.config.orderId || `order_${Date.now()}`,
        amount: this.config.amount,
        currency: this.config.currency,
        paymentMethod: 'DIRECT',
      })
      this.setState('qr')
      this.startPolling()
    } catch (err: any) {
      this.errorMessage = err.message
      this.setState('error')
      this.config.onError?.(err.message)
    }
  }

  private async startWalletPayment(wallet: DetectedWallet): Promise<void> {
    this.setState('loading')
    try {
      // 1. Create payment on server
      this.payment = await this.api.createPayment({
        apiKey: this.config.apiKey,
        orderId: this.config.orderId || `order_${Date.now()}`,
        amount: this.config.amount,
        currency: this.config.currency,
        paymentMethod: 'DIRECT',
      })

      // 2. Connect wallet
      this.setState('wallet-pending')
      await connectWallet(wallet.provider)

      // 3. Execute transaction
      const txHash = await executeTransaction(
        wallet.provider,
        this.payment.paymentAddress,
        this.payment.amount
      )

      // 4. Poll for confirmation
      this.setState('polling')
      this.startPolling()
    } catch (err: any) {
      // User rejected
      if (err.code === 4001 || err.message?.includes('rejected')) {
        this.setState('method-select')
        return
      }
      this.errorMessage = err.message
      this.setState('error')
      this.config.onError?.(err.message)
    }
  }

  // ─── Status Polling ───────────────────────────────────

  private startPolling(): void {
    if (!this.payment) return
    const paymentId = this.payment.paymentId

    this.pollInterval = setInterval(async () => {
      try {
        const status = await this.api.getPaymentStatus(paymentId)
        if (status.status === 'CONFIRMED') {
          this.stopPolling()
          this.setState('success')
          this.config.onSuccess?.(this.payment!)
        } else if (status.status === 'FAILED') {
          this.stopPolling()
          this.errorMessage = 'Payment failed on-chain'
          this.setState('error')
          this.config.onError?.('Payment failed')
        }
      } catch {}
    }, 5000) // Poll every 5s
  }

  private stopPolling(): void {
    if (this.pollInterval) {
      clearInterval(this.pollInterval)
      this.pollInterval = null
    }
  }

  // ─── QR Rendering ─────────────────────────────────────

  private renderQRToCanvas(canvas: HTMLCanvasElement, value: string): void {
    // Simple QR rendering using canvas 2D
    // For production, we use the qrcode npm package
    try {
      const QRCode = require('qrcode')
      QRCode.toCanvas(canvas, value, {
        width: 200,
        margin: 2,
        color: { dark: '#ffffff', light: '#16161f' },
      })
    } catch {
      // Fallback: just show the text
      canvas.style.display = 'none'
    }
  }

  // ─── Helpers ──────────────────────────────────────────

  private el(tag: string, className?: string): HTMLElement {
    const el = document.createElement(tag)
    if (className) el.className = className
    return el
  }
}
