// ─── CryptoPay SDK — Entry Point ────────────────────────────
// Exposes: window.CryptoPay + auto-init from data attributes

import { CryptoPayCheckout, CheckoutConfig } from './checkout'

export { CryptoPayCheckout } from './checkout'
export type { CheckoutConfig } from './checkout'
export { CryptoPayAPI } from './api'
export { detectWallets, connectWallet, executeTransaction } from './wallet'

/**
 * Create a checkout widget instance
 *
 * @example
 * ```js
 * const checkout = CryptoPay.createCheckout({
 *   apiKey: 'cpk_live_abc123',
 *   amount: '50.00',
 *   currency: 'USDT',
 *   onSuccess: (payment) => console.log('Paid!', payment),
 * })
 * checkout.mount('#payment-container')
 * ```
 */
export function createCheckout(config: CheckoutConfig): CryptoPayCheckout {
  return new CryptoPayCheckout(config)
}

/**
 * Auto-initialize from DOM elements with data-cryptopay attributes
 * Scans for elements with id="cryptopay-button" or class="cryptopay-checkout"
 */
function autoInit(): void {
  if (typeof document === 'undefined') return

  const elements = document.querySelectorAll<HTMLElement>(
    '#cryptopay-button, .cryptopay-checkout, [data-cryptopay]'
  )

  elements.forEach((el) => {
    const apiKey = el.dataset.apiKey || el.dataset.cryptopayApiKey
    const amount = el.dataset.amount || '0'
    const currency = el.dataset.currency || 'USDT'
    const orderId = el.dataset.orderId
    const baseUrl = el.dataset.baseUrl
    const theme = (el.dataset.theme as 'dark' | 'light') || 'dark'

    // Callback names from data attributes
    const onSuccessName = el.dataset.onSuccess
    const onErrorName = el.dataset.onError

    if (!apiKey) {
      console.warn('[CryptoPay] Missing data-api-key on element:', el)
      return
    }

    const config: CheckoutConfig = {
      apiKey,
      amount,
      currency,
      orderId,
      baseUrl,
      theme,
      onSuccess: onSuccessName
        ? (window as any)[onSuccessName]
        : undefined,
      onError: onErrorName
        ? (window as any)[onErrorName]
        : undefined,
    }

    const checkout = new CryptoPayCheckout(config)

    // Mount into the element itself
    const mountId = `cpay-mount-${Math.random().toString(36).slice(2, 8)}`
    el.id = el.id || mountId
    checkout.mount(`#${el.id}`)
  })
}

// Auto-init on DOMContentLoaded
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', autoInit)
  } else {
    autoInit()
  }
}

// Default export for module usage
export default { createCheckout, CryptoPayCheckout }
